-- Copiando estrutura do banco de dados para entrelacos
DROP DATABASE IF EXISTS `entrelacos`;
CREATE DATABASE IF NOT EXISTS `entrelacos` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin */;
USE `entrelacos`;

-- Copiando estrutura para tabela entrelacos.animais
DROP TABLE IF EXISTS `animais`;
CREATE TABLE IF NOT EXISTS `animais` (
  `id_animal` int(11) NOT NULL AUTO_INCREMENT,
  `id_ong` int(11) NOT NULL,
  `nome` varchar(100) NOT NULL,
  `especie` varchar(50) NOT NULL,
  `raca` varchar(100) DEFAULT NULL,
  `porte` varchar(20) NOT NULL,
  `idade` varchar(30) NOT NULL,
  `sexo` varchar(10) NOT NULL,
  `descricao` text NOT NULL,
  `status` varchar(20) NOT NULL,
  `imagem` longtext DEFAULT NULL,
  `ong` varchar(150) NOT NULL,
  `cidade` varchar(100) NOT NULL,
  `estado` char(2) NOT NULL,
  PRIMARY KEY (`id_animal`),
  KEY `fk_animais_ong` (`id_ong`),
  CONSTRAINT `fk_animais_ong` FOREIGN KEY (`id_ong`) REFERENCES `ong` (`id_ong`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Copiando dados para a tabela entrelacos.animais: ~7 rows (aproximadamente)
DELETE FROM `animais`;
INSERT INTO `animais` (`id_animal`, `id_ong`, `nome`, `especie`, `raca`, `porte`, `idade`, `sexo`, `descricao`, `status`, `imagem`, `ong`, `cidade`, `estado`) VALUES
	(49, 42, 'Thor', 'Cachorro', 'Labrador', 'Grande', '10 meses', 'Macho', 'Encontrado ainda filhote, este pequeno cachorro estava sozinho e precisava de cuidados. Mesmo sendo tão novo, mostrou ser muito curioso, brincalhão e carinhoso. Ele passou a receber cuidados e agora espera encontrar uma família responsável que possa oferecer muito amor, segurança e um lar para sempre.', 'Disponível', 'data:image/jpeg;base64,', 'patinhas fofas', 'Presidente Prudente', 'SP'),
	(50, 42, 'Juju', 'Cachorro', ' Border collie', 'Médio', '3 anos', 'Fêmea', 'Ela foi encontrada ainda jovem, sempre muito alegre e cheia de energia. Desde que recebeu cuidados, mostrou ser uma cachorra carinhosa, brincalhona e muito curiosa, conquistando todos ao seu redor com seu jeitinho divertido. Agora, espera encontrar uma família que lhe dê amor, carinho e um lar seguro para chamar de seu.', 'Disponível', 'data:image/jpeg;base64,', 'patinhas fofas', 'Presidente Prudente', 'SP'),
	(51, 42, 'Bella', 'Cachorro', 'Beagle', 'Médio', '5 meses', 'Fêmea', 'Ela foi encontrada ainda filhote, cheia de energia e com um jeitinho muito carinhoso. Desde que recebeu cuidados, mostrou ser uma cachorrinha brincalhona, curiosa e alegre, adorando receber atenção e carinho. Agora, com apenas 5 meses, espera encontrar uma família que lhe dê amor, cuidado e um lar seguro para crescer feliz.', 'Urgente', 'data:image/jpeg;base64,', 'patinhas fofas', 'Presidente Prudente', 'SP'),
	(52, 42, 'Molly', 'Gato', 'Vira-Lara', 'Médio', '1 ano', 'Fêmea', 'Ela foi encontrada ainda jovem e, desde então, mostrou ser uma gata tranquila, carinhosa e cheia de personalidade. Com apenas 1 ano, adora receber carinho e explorar tudo ao seu redor, conquistando todos com seu jeitinho especial. Agora, espera encontrar uma família que lhe dê amor, cuidado e um lar seguro para chamar de seu.', 'Adotado', 'data:image/jpeg;base64,', 'patinhas fofas', 'Presidente Prudente', 'SP'),
	(53, 42, 'Melman', 'Gato', 'Vira-lata', 'Médio', '2 anos', 'Macho', 'Ele foi encontrado ainda jovem e, desde então, mostrou ser um gato carinhoso, tranquilo e muito companheiro. Aos 2 anos, já tem um jeitinho próprio e adora receber atenção, explorar o ambiente e ficar perto das pessoas. Agora, espera encontrar uma família que lhe ofereça amor, cuidado e um lar seguro para viver feliz.', 'Disponível', 'data:image/jpeg;base64,', 'patinhas fofas', 'Presidente Prudente', 'SP'),
	(54, 42, 'Lenny', 'Gato', 'Vira-lata', 'Médio', '3 anos', 'Macho', 'Ele foi encontrado já adulto, mas logo mostrou ser um gato dócil, carinhoso e muito companheiro. Aos 3 anos, é tranquilo, gosta de receber carinho e aprecia a companhia das pessoas. Agora, espera encontrar uma família que lhe ofereça amor, cuidado e um lar seguro onde possa viver feliz.', 'Em Adoção', 'data:image/jpeg;base64,', 'patinhas fofas', 'Presidente Prudente', 'SP'),
	(55, 55, 'bing', 'Cachorro', 'Vira-lata', 'Médio', '2 anos', 'Macho', 'Ele foi encontrado nas ruas, mas hoje esta a procura de um novo lar.', 'Disponível', 'data:image/jpeg;base64,', 'Patinhas Fofas', 'Goiânia', 'GO');

