  `nome` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `senha` varchar(255) NOT NULL,
  `telefone` varchar(20) DEFAULT NULL,
  `tipo` enum('adotante','ong') DEFAULT 'adotante',
  `foto_perfil` longtext DEFAULT NULL,
