-- Copiando estrutura para tabela entrelacos.dicas
DROP TABLE IF EXISTS `dicas`;
CREATE TABLE IF NOT EXISTS `dicas` (
  `id_dica` int(11) NOT NULL AUTO_INCREMENT,
  `id_usuario` int(11) NOT NULL,
  `titulo` varchar(150) NOT NULL,
  `categoria` varchar(50) NOT NULL,
  `qualPet` varchar(50) NOT NULL,
  `conteudo` text NOT NULL,
  `data_criacao` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_dica`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Copiando dados para a tabela entrelacos.dicas: ~3 rows (aproximadamente)
DELETE FROM `dicas`;
INSERT INTO `dicas` (`id_dica`, `id_usuario`, `titulo`, `categoria`, `qualPet`, `conteudo`, `data_criacao`) VALUES
	(9, 44, 'Alimentos proibidos', 'Alimentação', 'Cachorro', 'Muitos alimentos comuns do nosso dia a dia são altamente tóxicos para os cães e podem causar sérios problemas de saúde.\n\nO que você NUNCA deve oferecer:\n\nChocolate e Café: Contêm teobromina e cafeína, substâncias que afetam gravemente o coração e o sistema nervoso.\n\nCebola e Alho: Destroem os glóbulos vermelhos do sangue, podendo levar à anemia severa.\n\nUvas e Uvas-Passas: Podem causar insuficiência renal aguda de forma rápida e imprevisível.\n\nOssos Cozidos: Podem soltar farpas pontiagudas ao serem mastigados, perfurando o estômago ou intestino.\n\nAbacate: Possui persina, uma substância que pode provocar intoxicação, vômitos e diarreia.', '2026-06-23 11:46:44'),
	(13, 44, 'Escovação dental', 'Saúde', 'Gato', 'A escovação regular evita o acúmulo de tártaro, mau hálito e doenças nas gengivas do seu gato.\n\nPasso a passo para uma escovação segura:\n\nProdutos específicos: Use sempre creme dental e escovas (ou dedeiras) desenvolvidas para felinos. Nunca use pasta de dente humana, pois ela é tóxica se engolida.\n\nAdaptação gradual: Deixe o gato sentir o gosto da pasta no seu dedo nos primeiros dias antes de introduzir a escova.\n\nEscovação suave: Faça movimentos circulares leves nos dentes caninos e molares. Não é necessário enxaguar.\n\nFrequência: O ideal é escovar de 2 a 3 vezes por semana para manter a saúde bucal em dia.', '2026-07-28 12:04:38'),
	(21, 44, 'lavagem de pata', 'Saúde', 'Cachorro', 'A higienização das patas após os passeios é essencial para proteger a saúde do seu cão e manter a casa limpa.\n\nComo fazer a limpeza correta:\n\nProdutos adequados: Use apenas água morna com shampoo/sabonete neutro próprio para pets ou lenços umedecidos veterinários.\n\nO que evitar: Nunca utilize álcool em gel, desinfetantes ou detergentes domésticos, pois causam queimaduras, alergias e ressecamento nas almofadinhas (coxinhas).\n\nCuidado na lavagem: Lave suavemente a parte inferior e os espaços entre os dedos, removendo sujeiras, sujeira de rua ou produtos químicos do asfalto.\n\nSecagem reforçada: O passo mais importante é secar muito bem entre as patas e os dedos com uma toalha limpa. A umidade acumulada nessa região favorece o surgimento de fungos e dermatites.', '2026-08-27 16:34:02');

-- Copiando estrutura para tabela entrelacos.doacao
DROP TABLE IF EXISTS `doacao`;
CREATE TABLE IF NOT EXISTS `doacao` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_usuario` int(11) DEFAULT NULL,
  `nome_ong` varchar(150) NOT NULL,
  `cidade_ong` varchar(100) NOT NULL,
  `categoria` varchar(50) NOT NULL,
  `classificacao` varchar(30) NOT NULL,
  `item` varchar(200) NOT NULL,
  `quantidade` varchar(100) DEFAULT NULL,
  `descricao` text NOT NULL,
  `local_entrega` varchar(255) NOT NULL,
  `tipo_entrega` varchar(50) NOT NULL,
  `tipo_pix` varchar(30) DEFAULT NULL,
  `pix` varchar(255) DEFAULT NULL,
  `banco` varchar(100) DEFAULT NULL,
  `conta` varchar(100) DEFAULT NULL,
  `data_cadastro` timestamp NOT NULL DEFAULT current_timestamp(),
  `data_atualizacao` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

