INSERT INTO `doacao` (`id`, `id_usuario`, `nome_ong`, `cidade_ong`, `categoria`, `classificacao`, `item`, `quantidade`, `descricao`, `local_entrega`, `tipo_entrega`, `tipo_pix`, `pix`, `banco`, `conta`, `data_cadastro`, `data_atualizacao`) VALUES
	(2, 44, 'Anjos de Quatro Patas', 'Campinas', 'Acessórios', 'Alta', 'Casinhas de plástico (tamanho G e GG) e Cobertores', '15 casinhas / 40 cobertores', 'Com a chegada das frentes frias, precisamos estruturar os baías externas para garantir conforto térmico aos cães de grande porte resgatados.', 'Av. Francisco Glicério, 1200 - Centro', 'Entrega na ONG', 'Telefone', '(19) 98765-4321', 'Bradesco', 'Ag: 3210 / CC: 54321-0', '2026-09-08 11:18:42', '2026-10-01 13:04:34'),
	(8, 44, 'patinhas fofas', 'Presidente Prudente', 'Alimentação', 'Alta', 'Ração para cães adultos e filhotes', '150 kg', 'Estamos com o estoque de ração no limite e precisamos abastecer o abrigo para alimentar os 45 cães resgatados este mês. Aceitamos sacos fechados de qualquer marca.', 'Av. Manoel Goulart, 500 - Centro', 'Ponto de coleta', 'E-mail', 'contato@patinhasfofas.org.br', 'Banco do Brasil', 'Ag: 1234-5 / CC: 98765-4', '2026-09-08 16:03:11', '2026-10-01 11:42:13'),
	(9, 44, 'Adote um Gatinho', 'São José do Rio Preto', 'Alimentação', 'Urgente', 'Areia Sanitária e Ração Castrados (Sachês)', '80 sacos de areia (4kg) / 200 sachês', 'Estamos com superpopulação no gatil após o resgate de uma colônia. Precisamos de areia sanitária para os banheiros e ração úmida para os gatos em recuperação pós-castração.', 'Rua Portugal, 310 - Jardim Europa', 'Ponto de coleta', 'E-mail', 'ajude@adoteumgatinho.org.br', 'Inter', 'Ag: 0001 / Conta: 9876543-2', '2026-10-01 11:45:12', '2026-10-01 11:45:12');

